const publishMedia = Array.isArray(vars.images) ? vars.images : []
const publishHasVideo = publishMedia.some(path => /^data:video\//i.test(String(path || '')) || /\.(3g2|3gp|avi|m2ts|m4v|mkv|mov|mp4|mpeg|mpg|ogv|webm|wmv)(?:[?#].*)?$/i.test(String(path || '')))
const publishTimeoutMs = publishHasVideo ? 180000 : 60000
// Match the existing Group visibility check; a disabled button still exists.
async function postSubmitButtonIsVisible(selector) {
  return await page.evaluate(`
    const result = document.evaluate(__args[0], document, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
    for (let i = 0; i < result.snapshotLength; i++) {
      const el = result.snapshotItem(i);
      const style = window.getComputedStyle(el);
      if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') continue;
      const rect = el.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) return true;
    }
    return false;
  `, selector);
}

const btn = await helpers.element('fb_post_button')
await page.waitForSelector(btn, { timeout: 10000 })
await page.click(btn)
vars.facebookPostPublishStartedAt = Date.now()
if (input.verifyPostAfterClick === true) {
  while (true) {
    if (signal.aborted) throw new Error('Đã dừng chờ xác nhận đăng bài')
    if (!await postSubmitButtonIsVisible(btn)) {
      return { ok: true, posted: true, submitClosed: true, publishTimeoutMs }
    }
    const remainingMs = publishTimeoutMs - (Date.now() - vars.facebookPostPublishStartedAt)
    if (remainingMs <= 0) throw new Error('Form đăng bài chưa đóng sau ' + (publishTimeoutMs / 1000) + ' giây')
    await helpers.sleep(Math.min(500, remainingMs), signal)
  }
}
// Group retains its separate verify block and frequency-limit policy.
await helpers.sleep(3000, signal)
return { posted: true }
